def choose_move(observation):
    def is_num(x):
        return type(x) in (int, float)

    def is_pos(x):
        return isinstance(x, (list, tuple)) and len(x) == 2 and is_num(x[0]) and is_num(x[1])

    def clamp1(v):
        return -1 if v < -0.5 else (1 if v > 0.5 else 0)

    def get_pos(obj):
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "xy", "coord", "coords"):
                v = obj.get(k)
                if is_pos(v):
                    return [v[0], v[1]]
            for k in ("self", "me", "agent", "player", "unit"):
                v = obj.get(k)
                p = get_pos(v)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            if is_pos(obj):
                return [obj[0], obj[1]]
            for item in obj:
                p = get_pos(item)
                if p is not None:
                    return p
        return None

    def flatten_entities(obj, out):
        if isinstance(obj, dict):
            if is_pos(obj.get("position")) or is_pos(obj.get("pos")) or is_pos(obj.get("location")):
                out.append(obj)
            for v in obj.values():
                flatten_entities(v, out)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                flatten_entities(v, out)

    def score_entity(ent):
        s = 0
        if isinstance(ent, dict):
            t = str(ent.get("type", ent.get("kind", ent.get("name", "")))).lower()
            if any(w in t for w in ("resource", "food", "coin", "gem", "gold", "treasure")):
                s += 8
            if any(w in t for w in ("enemy", "opponent", "adversary", "pursuer", "hunter")):
                s -= 2
            if any(w in t for w in ("territory", "zone", "cell", "tile", "claim")):
                s += 3
            if ent.get("owner") is not None:
                s += 1
        return s

